    return d + ` L ${W} ${mid} Z`;
  };
  const line = pick => points.map((p, i) =>
    `${i ? 'L' : 'M'} ${x(i).toFixed(1)} ${y(pick(p)).toFixed(1)}`).join(' ');

  const grid = [0.5, 0.25, -0.25, -0.5].map(f =>
    `<line x1="0" y1="${y(peak * f).toFixed(1)}" x2="${W}" y2="${y(peak * f).toFixed(1)}" stroke="#1f2942"/>`).join('');
