function render(s) {
  const d = new Date(s.instant), hour = d.getUTCHours() + d.getUTCMinutes() / 60;

  $('sky').style.background = skyFor(hour, s.irradianceFactor);
  $('date').textContent = d.toUTCString().slice(0, 16);
