    $('batKw').textContent = b.powerKw.toFixed(1);
    $('socFill').style.width = b.stateOfChargePercent + '%';
    $('socText').textContent = `${b.stateOfChargePercent.toFixed(1)}%  ·  ${b.stateOfChargeKwh.toFixed(0)} / ${b.capacityKwh.toFixed(0)} kWh`;
    $('batIn').textContent = b.chargedKwh.toFixed(0);
    $('batOut').textContent = b.dischargedKwh.toFixed(0);
    $('stratName').textContent = b.strategy;
  } else {
    $('batteryPanel').style.display = 'none';
  }

  $('houses').innerHTML = s.houses.map(h => {
    const cls = h.netPowerKw < 0 ? 'exp' : 'imp';
    const icons = h.assets.filter(a => ICONS[a]).map(a => ICONS[a]).join('');
